SELECT id, symbol, interval_code, decision, original_decision, candle_open_time, generated_at, created_at, final_entry_allowed, atr_immediate_entry_allowed, atr_recommended_position_percent, atr_entry_type, total_score, confidence_score FROM crypto_ai.trade_signal WHERE id IN (159285,159407,159408,165289,165412,165415,167616,167668,171559,171589,176655,176710) ORDER BY symbol, generated_at;
SELECT COUNT(*) AS boundary_pairs, SUM(f.generated_at > o.generated_at) AS five_after_one, SUM(f.decision <> pf.decision) AS five_changed_vs_prior FROM crypto_ai.trade_signal o JOIN crypto_ai.trade_signal f ON f.symbol=o.symbol AND f.interval_code='5m' AND f.candle_open_time = o.candle_open_time - INTERVAL 4 MINUTE LEFT JOIN crypto_ai.trade_signal pf ON pf.symbol=o.symbol AND pf.interval_code='5m' AND pf.candle_open_time = f.candle_open_time - INTERVAL 5 MINUTE WHERE o.interval_code='1m' AND o.generated_at BETWEEN '2026-10-11 00:00:00' AND '2026-10-13 00:00:00';